  a.confirmations.push({taskId:task.id,point:ALL[task.target].name,manifest:task.manifest.map(m=>({...m}))});
  addLog('back','物流运输配送系统','转运点自动签收：<b>'+ALL[task.target].name+'</b>确认收到'+summary+'；后续投送环节已自动衔接。');
