function fitLogisticsView(){
 const a=S.logistics;if(!a)return;
 if(M.online){
  if(M.focusM){M.map.removeLayer(M.focusM);M.focusM=null;}
  const ids=logisticsHighlightedPointIds(a);
  const left=document.querySelector('.panel-left')?.getBoundingClientRect().width||330,right=document.querySelector('.panel-right')?.getBoundingClientRect().width||350;
  M.map.flyToBounds(L.latLngBounds(ids.map(ll)),{paddingTopLeft:[left+45,240],paddingBottomRight:[right+45,160],maxZoom:11.5,duration:1.1});
  const candidates=new Set(a.warehouses.map(w=>w.id)),selected=new Set(matchedWarehouseIds());
  const selectionComplete=logisticsWarehouseSelectionComplete(a);
  POINTS.forEach(p=>{
   if(p.id===LOGISTICS_CFG.handoff&&!logisticsTransferPointVisible(a)){M.nodeMarkers[p.id]?.setOpacity(0);return;}
   if(p.type==='town'&&!M.showPoint(p)){M.nodeMarkers[p.id]?.setOpacity(0);return;}
   M.nodeMarkers[p.id]?.setOpacity(candidates.has(p.id)?(selectionComplete?(selected.has(p.id)?1:0):ids.includes(p.id)?1:.24):ids.includes(p.id)?1:.24);
  });
 }else{
  FB.focusId=null;const warehouseIds=logisticsWarehouseSelectionComplete(a)?matchedWarehouseIds():a.warehouses.map(w=>w.id);
  const pts=[ALL[INCIDENT.epic],...warehouseIds.map(id=>ALL[id])];
  if(S.step>=5&&a.routes.some(r=>r.detoured))pts.push(ALL[LOGISTICS_CFG.detour]);
  if(logisticsTransferPointVisible(a))pts.push(ALL[LOGISTICS_CFG.handoff]);
  const xs=pts.map(p=>p.x),ys=pts.map(p=>p.y);
  const x=Math.min(...xs)-110,y=Math.min(...ys)-90,w=Math.max(...xs)-x+130,h=Math.max(...ys)-y+110;
  document.getElementById('mapFallback').setAttribute('viewBox',`${x} ${y} ${w} ${h}`);
 }
 S.routesDirty=true;
}
function routePosition(route,fraction=.5){
 const points=route.via.map(ll),segments=points.slice(1).map((p,i)=>Math.hypot(p[0]-points[i][0],p[1]-points[i][1]));
 const at=segments.reduce((n,v)=>n+v,0)*fraction;let acc=0;
 for(let i=0;i<segments.length;i++){if(acc+segments[i]>=at){const t=segments[i]?(at-acc)/segments[i]:0;return[points[i][0]+(points[i+1][0]-points[i][0])*t,points[i][1]+(points[i+1][1]-points[i][1])*t];}acc+=segments[i];}
 return points.at(-1);
}
function logisticsMarker(position,html,className='',offset=[0,0]){
 return L.marker(position,{icon:L.divIcon({className:'mk '+className,html:'<div style="margin-left:'+offset[0]+'px;margin-top:'+offset[1]+'px">'+html+'</div>',iconSize:[0,0],iconAnchor:[0,0]}),interactive:false,zIndexOffset:800}).addTo(M.routeL);
}
function drawLogisticsMap(){
 const a=S.logistics;if(!a||!M.online)return;
 L.circle(ll(INCIDENT.epic),{radius:INCIDENT.radiusKm*1000,color:'#ff7770',weight:2,fillOpacity:.1,interactive:false}).addTo(M.routeL);
 if(S.step>=2){
  const selectionComplete=logisticsWarehouseSelectionComplete(a);
  const warehouses=selectionComplete?a.warehouses.filter(w=>matchedWarehouseIds().includes(w.id)):a.warehouses;
  warehouses.forEach((w,i)=>{
   if(selectionComplete){
    logisticsMarker(ll(w.id),'<div class="warehouse-halo selected"></div>');
    return;
   }
   const status=S.step===2?'正在核对可调拨库存':'正在比对需求与库存';
   const labelSide=['','west','south','west south'][i%4];
   logisticsMarker(ll(w.id),'<div class="warehouse-halo"></div><div class="warehouse-callout '+labelSide+'"><b>'+ALL[w.id].name+'</b><small>直线 '+w.distance.toFixed(1)+' km · '+status+'</small></div>');
  });
 }
 if((S.step===4||S.step===5)&&a.initialRoutes.some(r=>r.geo?.length>1)){
  a.initialRoutes.forEach((r,i)=>{
   if(!r.geo||r.geo.length<2)return;
   if(S.step===5&&!a.routes.some(route=>route.depot===r.depot&&route.detoured))return;
   const color=['#70c7ff','#b29aff','#57dac3'][i%3];
   L.polyline(r.geo,{color:S.step===5?'#aeb7c6':color,weight:S.step===5?3:3.5,opacity:S.step===5?.38:.88,dashArray:'7 6',lineCap:'round',lineJoin:'round'}).addTo(M.routeL);
   const anchor=r.geo[Math.floor(r.geo.length*.55)];
   logisticsMarker(anchor,'<div class="route-badge" style="--route-color:'+(S.step===5?'#aeb7c6':color)+'"><b>'+r.name+' · '+(S.step===5?'封闭前原路线':'初始路线')+'</b><br>'+r.dist.toFixed(1)+' km · 约 '+Math.ceil(r.dur)+' 分钟</div>');
  });
 }
 /* 封路红线只用于路线核验；调拨启动后保留绕行方案，不再显示已剔除路段。 */
 if(S.step===5)a.blockedInfo.forEach(b=>{
  const road=b.geoPath?.length>1?b.geoPath:LOGISTICS_CLOSED_ROAD.path.map(([lat,lng])=>{const p=wgs2gcj(lng,lat);return[p[0],p[1]];});
  L.polyline(road,{color:'#171018',weight:10,opacity:.9,lineCap:'round',lineJoin:'round',interactive:false}).addTo(M.routeL);
  L.polyline(road,{color:'#ff3f43',weight:6,opacity:1,lineCap:'round',lineJoin:'round',interactive:false}).addTo(M.routeL);
  const pos=b.position||(()=>{const p=wgs2gcj(b.lng,b.lat);return[p[0],p[1]];})();
  L.circleMarker(pos,{radius:15,color:'#ff706e',weight:2.5,fillColor:'#ff4747',fillOpacity:.12,interactive:false}).addTo(M.routeL);
  logisticsMarker(pos,'<div class="hazard-cross">×</div><div class="hazard-caption">道路封闭 · 已剔除</div>','',[-12,-12]).setZIndexOffset(1800);
 });
 if(a.planned&&S.step>=5){
  if(a.routes.some(r=>r.detoured))logisticsMarker(ll(LOGISTICS_CFG.detour),'<div class="route-badge" style="--route-color:#ffd166"><b>S105 绕行点</b></div>','',[58,-12]);
  a.routes.forEach((r,i)=>{
   const position=a.warehouses.findIndex(w=>w.id===r.depot),color=r===a.fastest?'#49dfac':['#6d9fff','#74b4f7','#95a8ed'][position];
   if(r.geo&&r.geo.length>1)L.polyline(r.geo,{color,weight:r===a.fastest?5:3,opacity:r.roadVerified===false ? .52 : r.roadVerified===null ? .62 : .9,dashArray:r.roadVerified===true?null:'6 7'}).addTo(M.routeL);
   const anchor=r.geo?r.geo[Math.floor(r.geo.length*.5)]:ll(r.depot);
   const roadStatus=r.roadVerified===true?'<br>'+r.dist.toFixed(1)+' km · 约 '+Math.ceil(r.dur)+' 分钟':r.roadVerified===false?'<br>道路服务未连接<br>仅供示意':'<br>实时路网校准中…';
   const routeLabel=S.step===5?(r.detoured?'S105绕行路线':'畅通配送路线'):'协同配送路线';
   logisticsMarker(anchor,'<div class="route-badge" style="--route-color:'+color+'"><b>'+r.name+' · '+routeLabel+'</b>'+roadStatus+'</div>','',[position===1?-55:position===2?-65:30,position===2?48:-15]);
  });
 }
 if(S.step>=6&&a.planned){
  const air=a.airRoute,team=a.teamRoute;
  L.polyline(air.via.map(ll),{color:'#50e3ed',weight:3,dashArray:'5 6'}).addTo(M.routeL);
  L.polyline(team.via.map(ll),{color:'#eebd72',weight:3.5,dashArray:'4 5'}).addTo(M.routeL);
  const size=M.map.getSize(),mapRect=M.map.getContainer().getBoundingClientRect(),village=M.map.latLngToContainerPoint(ll(INCIDENT.epic));
  const panelRect=document.querySelector('.panel-right')?.getBoundingClientRect(),panelLeft=panelRect?panelRect.left-mapRect.left:size.x-350;
  const dockWidth=Math.max(160,Math.min(220,panelLeft-32)),dockX=Math.max(12,panelLeft-dockWidth-14);
  const labels=[
   {anchor:routePosition(air,.65),color:'#50e3ed',html:'<div class="route-badge route-dock" style="--route-color:#50e3ed;--dock-width:'+dockWidth+'px"><b>无人机 · 先期投送</b><br>'+air.dist.toFixed(1)+' km · '+Math.ceil(air.dur)+' 分钟</div>'},
   {anchor:routePosition(team,.5),color:'#eebd72',html:'<div class="route-badge route-dock" style="--route-color:#eebd72;--dock-width:'+dockWidth+'px"><b>救援人员 · 安全通道接驳</b><br>'+team.dist.toFixed(1)+' km · '+Math.ceil(team.dur)+' 分钟</div>'},
   {anchor:ll(LOGISTICS_CFG.handoff),color:'#eebd72',html:'<div class="transfer-label route-dock" style="--route-color:#eebd72;--dock-width:'+dockWidth+'px">沙坝村安全转运点<br>车辆卸载 → 人员 / 无人机接驳</div>'}
  ];
  const dockStep=62,dockSpan=(labels.length-1)*dockStep,dockInset=25,callouts=[];
  const maxDockY=Math.max(dockInset,size.y-dockInset-dockSpan);
  const dockY=Math.max(dockInset,Math.min(village.y-dockSpan/2,maxDockY));
  labels.forEach((label,i)=>{const at=M.map.containerPointToLatLng([dockX,dockY+i*dockStep]),marker=logisticsMarker(at,label.html);callouts.push({label,marker});});
  requestAnimationFrame(()=>{
   if(!M.map||S.logistics!==a||S.step<6)return;
   const rect=M.map.getContainer().getBoundingClientRect();
   callouts.forEach(({label,marker})=>{
    if(!M.routeL.hasLayer(marker))return;
    const frame=marker.getElement()?.querySelector('.route-dock');if(!frame)return;
    const box=frame.getBoundingClientRect(),end=M.map.containerPointToLatLng([box.left-rect.left,box.top+box.height/2-rect.top]);
    L.polyline([label.anchor,end],{color:label.color,weight:1.5,dashArray:'3 4',opacity:.82,interactive:false}).addTo(M.routeL);
   });
  });
 }
}
